func hexBytes(_ s: String) -> [UInt8] { Hex.decode(s) }

final class Cloud115CryptoTests: XCTestCase {
    private let ones: (Int) -> [UInt8] = { [UInt8](repeating: 1, count: $0) }

    // ---- m115 ----

    func testM115EncodeMatchesP115RsaCipher() {
        XCTAssertEqual(V.m115EncodeB64, M115.encode(Array(V.m115EncodePlain.utf8), key: [UInt8](repeating: 0, count: 16), padSource: ones))
        XCTAssertEqual(V.m115EncodeLongB64, M115.encode(Array(V.m115EncodeLongPlain.utf8), key: [UInt8](repeating: 0, count: 16), padSource: ones))
    }

    func testM115DecodeXorStageMatchesP115RsaCipher() throws {
        XCTAssertEqual(hexBytes(V.m115DecodeXorOut), try M115.decodeXor(hexBytes(V.m115DecodeXorIn), key: [UInt8](repeating: 0, count: 16)))
    }

    func testM115EncodeIsRandomizedButSizedPerRsaBlock() {
        let key = M115.generateKey()
        let a = Data(base64Encoded: M115.encode([UInt8](repeating: 0, count: 10), key: key))!
        let b = Data(base64Encoded: M115.encode([UInt8](repeating: 0, count: 10), key: key))!
        XCTAssertEqual(128, a.count)
        XCTAssertNotEqual(a, b)
        XCTAssertEqual(256, Data(base64Encoded: M115.encode([UInt8](repeating: 0, count: 200), key: key))!.count)
    }

    /// RSA public-exponent round trip: what the server "signs" with its private key we can't reproduce, but
    /// encrypt (PKCS#1 type 2) followed by the public-key operation must be undone by the modulus structure.
    func testM115RsaDecryptStripsPadding() {
        // A block whose RSA "decryption" (x^e mod n) we know: pick x = m^d is impossible without d, so check
        // padding stripping on a constructed plaintext by verifying decrypt(encrypt-without-RSA) logic via BigUInt.
        let m = BigUInt(bytes: [0x00, 0x01, 0xff, 0xff, 0x00, 0x41, 0x42])
        XCTAssertEqual(m.bytes, [0x01, 0xff, 0xff, 0x00, 0x41, 0x42])
    }

    // ---- ECDH / AES / LZ4 / token ----

    func testRemotePublicKeyIsOnP224() {
        let p = P224.Point(x: BigUInt(bytes: Ec115Cipher.remotePub[0..<28]), y: BigUInt(bytes: Ec115Cipher.remotePub[28..<56]))
        XCTAssertTrue(P224.isOnCurve(p))
        XCTAssertTrue(P224.isOnCurve(P224.g))
        XCTAssertNil(P224.mul(P224.g, P224.n)) // n*G = infinity
    }

    func testEcdhMatchesPycaCryptography() throws {
        let c = try Ec115Cipher.fromPrivate(BigUInt(hex: V.ecPriv)!)
        XCTAssertEqual(V.ecPubToken, Hex.lowerHex(c.pubKey))
        let secret = hexBytes(V.ecSecret)
        XCTAssertEqual(Array(secret[0..<16]), c.key)
        XCTAssertEqual(Array(secret[12..<28]), c.iv)
    }

    func testEcdhRandomKeysDiffer() {
        let c1 = Ec115Cipher.create()
        let c2 = Ec115Cipher.create()
        XCTAssertEqual(30, c1.pubKey.count)
        XCTAssertNotEqual(c1.key, c2.key)
    }

    private var fixed: Ec115Cipher { Ec115Cipher(key: hexBytes(V.aesKey), iv: hexBytes(V.aesIv), pubKey: hexBytes(V.aesPub)) }

    func testAesEncryptMatchesCbcPkcs7() {
        XCTAssertEqual(V.aesEncCipher, Hex.lowerHex(fixed.encrypt(Array(V.aesEncPlain.utf8))))
    }

    func testAesDecryptWithLz4MatchesPythonLz4() throws {
        XCTAssertEqual(V.aesDecPlain, String(decoding: try fixed.decrypt(hexBytes(V.aesDecCipher)), as: UTF8.self))
    }

    func testAesFips197Vector() {
        let aes = AES128(key: hexBytes("000102030405060708090a0b0c0d0e0f"))
        let ct = aes.encryptBlock(hexBytes("00112233445566778899aabbccddeeff")[...])
        XCTAssertEqual("69c4e0d86a7b0430d8cdb78070b4c55a", Hex.lowerHex(ct))
        XCTAssertEqual("00112233445566778899aabbccddeeff", Hex.lowerHex(aes.decryptBlock(ct[...])))
    }

    func testTokenMatchesP115Cipher() {
        XCTAssertEqual(V.tokenB64, fixed.encodeToken(timestamp: 1_700_000_000, r1: 0, r2: 0))
        let t = [UInt8](Data(base64Encoded: fixed.encodeToken(timestamp: 1_700_000_000))!)
        XCTAssertEqual(48, t.count)
        let r1 = t[15], r2 = t[39]
        var pub = [UInt8](repeating: 0, count: 30)
        for i in 0..<15 { pub[i] = t[i] ^ r1 }
        for i in 0..<15 { pub[15 + i] = t[24 + i] ^ r2 }
        XCTAssertEqual(fixed.pubKey, pub)
        var ts: Int64 = 0
        for i in 0..<4 { ts |= Int64(t[20 + i] ^ r1) << (8 * Int64(i)) }
        XCTAssertEqual(1_700_000_000, ts)
    }

    func testLz4HandlesMatchesAndLongLiterals() throws {
        // literal "abc" then match offset 3 len 9 -> "abcabcabcabc", then literal tail "xyz"
        let block: [UInt8] = [0x35, 0x61, 0x62, 0x63, 3, 0, 0x30, 0x78, 0x79, 0x7a]
        XCTAssertEqual("abcabcabcabcxyz", String(decoding: try LZ4.decompressBlock(block, offset: 0, length: block.count), as: UTF8.self))
    }

    // ---- upload signatures ----

    func testUploadSigAndTokenMatchP115Cipher() {
        let fileId = "DA39A3EE5E6B4B0D3255BFEF95601890AFD80709"
        XCTAssertEqual(V.sig, Cloud115Hash.uploadSignature(userId: "12345", userKey: "4B1C0FFEE", fileId: fileId, target: "U_1_0"))
        XCTAssertEqual(V.token, Cloud115Hash.uploadToken(userId: "12345", fileId: fileId, fileSize: "1048576", signKey: "", signVal: "", timestamp: "1700000000123", appVer: "27.0.5.7"))
        XCTAssertEqual(V.token2, Cloud115Hash.uploadToken(userId: "12345", fileId: fileId, fileSize: "1048576", signKey: "abc", signVal: "0123ABCD", timestamp: "1700000000123", appVer: "27.0.5.7"))
    }

    // ---- OSS V1 signature: vectors from Aliyun's official Python SDK (oss2 2.x, ProviderAuth) ----

    func testOssSignatureMatchesAliyunOss2Sdk() {
        let secret = "OtxrzxIsfpFjA7SwPzILwy8Bw21TLhquhboDYROV"
        XCTAssertEqual("fV5fq7DPwNbrrig7nvUSZIVyruI=", Cloud115OSS.sign(
            secret: secret, method: "PUT", contentMD5: "ODBGOERFMDMzQTczRUY3NUE3NzA5QzdFNUYzMDQxNEM=", contentType: "text/html",
            date: "Thu, 17 Nov 2005 18:49:58 GMT",
            ossHeaders: ["X-OSS-Meta-Author": "foo@example.com", "X-OSS-Magic": "abracadabra"], resource: "/oss-example/nelson"))
        let date = "Wed, 11 Nov 2026 07:00:00 GMT"
        let sts = ["x-oss-security-token": "STOKEN"]
        XCTAssertEqual("R9hdrNdfG7fTNJjeehU2MBzscW0=", Cloud115OSS.sign(
            secret: secret, method: "PUT", contentMD5: "", contentType: "application/octet-stream", date: date, ossHeaders: sts,
            resource: "/oss-example/nelson?partNumber=3&uploadId=UPID"))
        XCTAssertEqual("4qNu/2QmcrVVOoeN/LeUwSantFg=", Cloud115OSS.sign(
            secret: secret, method: "POST", contentMD5: "", contentType: "application/octet-stream", date: date, ossHeaders: sts,
            resource: "/oss-example/nelson?uploads"))
    }

    func testOssHttpDate() {
        XCTAssertEqual("Thu, 17 Nov 2005 18:49:58 GMT", Cloud115OSS.httpDate(Date(timeIntervalSince1970: 1_132_253_398)))
    }
}

final class HashAndBigIntTests: XCTestCase {
    func testPortableHashesMatchKnownVectors() {
        func h(_ k: HashKind, _ s: String) -> String { var p = PortableHash(k); p.update(Array(s.utf8)); return Hex.lowerHex(p.finalize()) }
        XCTAssertEqual("da39a3ee5e6b4b0d3255bfef95601890afd80709", h(.sha1, ""))
        XCTAssertEqual("a9993e364706816aba3e25717850c26c9cd0d89d", h(.sha1, "abc"))
        XCTAssertEqual("84983e441c3bd26ebaae4aa1f95129e5e54670f1", h(.sha1, "abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq"))
        XCTAssertEqual("d41d8cd98f00b204e9800998ecf8427e", h(.md5, ""))
        XCTAssertEqual("9e107d9d372bb6826bd81d3542a419d6", h(.md5, "The quick brown fox jumps over the lazy dog"))
        XCTAssertEqual("57edf4a22be3c955ac49da2e2107b67a", h(.md5, String(repeating: "1234567890", count: 8)))
        XCTAssertEqual("e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855", h(.sha256, ""))
        XCTAssertEqual("248d6a61d20638b8e5c026930c3e6039a33ce45964ff2167f6ecedd419db06c1", h(.sha256, "abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq"))
        // incremental, odd chunking == one shot
        let big = (0..<100_000).map { UInt8(truncatingIfNeeded: $0 &* 31 &+ 7) }
        var a = PortableHash(.sha1)
        var i = 0
        while i < big.count { let n = min(777, big.count - i); a.update(Array(big[i..<(i + n)])); i += n }
        XCTAssertEqual(Hex.lowerHex(IncrementalHash.digest(.sha1, Data(big))), Hex.lowerHex(a.finalize()))
        var m = PortableHash(.md5); m.update(big)
        XCTAssertEqual(Hex.lowerHex(IncrementalHash.digest(.md5, Data(big))), Hex.lowerHex(m.finalize()))
        var s = PortableHash(.sha256); s.update(big)
        XCTAssertEqual(Hex.lowerHex(IncrementalHash.digest(.sha256, Data(big))), Hex.lowerHex(s.finalize()))
    }

    func testHmacSha1Rfc2202() {
        XCTAssertEqual("b617318655057264e28bc0b6fb378c8ef146be00",
                       Hex.lowerHex(HMAC_SHA1.mac(key: [UInt8](repeating: 0x0b, count: 20), message: Array("Hi There".utf8))))
        XCTAssertEqual("effcdf6ae5eb2fa2d27416d5f184df9c259a7c79",
                       Hex.lowerHex(HMAC_SHA1.mac(key: Array("Jefe".utf8), message: Array("what do ya want for nothing?".utf8))))
        XCTAssertEqual("aa4ae5e15272d00e95705637ce8a3b55ed402112",
                       Hex.lowerHex(HMAC_SHA1.mac(key: [UInt8](repeating: 0xaa, count: 80), message: Array("Test Using Larger Than Block-Size Key - Hash Key First".utf8))))
    }

    func testCrc32() {
        var c = CRC32(); c.update(Array("123456789".utf8))
        XCTAssertEqual(0xCBF43926, c.value)
    }

    func testBigUIntArithmetic() {
        let a = BigUInt(hex: "123456789abcdef0fedcba9876543210ffffffffffffffff0000000000000001")!
        let b = BigUInt(hex: "fedcba98765432100123456789abcdef")!
        let (q, r) = a.quotientAndRemainder(dividingBy: b)
        XCTAssertEqual(q * b + r, a)
        XCTAssertTrue(r < b)
        XCTAssertEqual(BigUInt(hex: "ffffffffffffffff")! + BigUInt(1), BigUInt(hex: "010000000000000000")!)
        XCTAssertEqual(BigUInt(hex: "010000000000000000")! - BigUInt(1), BigUInt(hex: "ffffffffffffffff")!)
        // Fermat: a^(p-1) = 1 mod p for prime p (P-224 field prime)
        let x = BigUInt(hex: "0badc0ffee0ddf00d")!
        XCTAssertEqual(x.power(P224.p - BigUInt(1), modulus: P224.p), BigUInt(1))
        let inv = x.inverse(modulus: P224.p)!
        XCTAssertEqual(x * inv % P224.p, BigUInt(1))
        // pseudo-random division checks
        var seed: UInt64 = 0x9E3779B97F4A7C15
        func next() -> UInt32 { seed = seed &* 6364136223846793005 &+ 1442695040888963407; return UInt32(truncatingIfNeeded: seed >> 33) }
        for _ in 0..<200 {
            let n = BigUInt(limbs: (0..<Int(next() % 40 + 1)).map { _ in next() })
            let d = BigUInt(limbs: (0..<Int(next() % 20 + 1)).map { _ in next() })
            if d.isZero { continue }
            let (qq, rr) = n.quotientAndRemainder(dividingBy: d)
            XCTAssertEqual(qq * d + rr, n)
            XCTAssertTrue(rr < d)
        }
    }
}
